/* ARQUIVO CÍVICO BR — dados primários e visualização neutra. Sem integração de IA. */
(()=>{'use strict';
const SEED=window.ARCHIVE_SEED||{parties:[],senators:[],historical:[],federations:[],changes:[],meta:{}};
const CAM='https://dadosabertos.camara.leg.br/api/v2';
const SEN='https://adm.senado.gov.br/adm-dadosabertos/api/v1/senadores?formato=json';
const URLS={TSE:'https://www.tse.jus.br/partidos/partidos-registrados-no-tse',FED:'https://www.tse.jus.br/partidos/federacoes-registradas-no-tse',CAM:'https://dadosabertos.camara.leg.br/swagger/api.html',SEN:'https://www12.senado.leg.br/dados-abertos/legislativo/parlamentares/senadores-em-exercicio',TSE_DATA:'https://dadosabertos.tse.jus.br/group/candidatos',CGU:'https://portaldatransparencia.gov.br/',TCU:'https://portal.tcu.gov.br/',STF:'https://portal.stf.jus.br/',STJ:'https://www.stj.jus.br/',PLANALTO:'https://www.planalto.gov.br/ccivil_03/',CAM_PROJ:'https://www.camara.leg.br/propostas-legislativas'};
const $=(q,r=document)=>r.querySelector(q),$$=(q,r=document)=>[...r.querySelectorAll(q)];
const esc=x=>String(x??'').replace(/[&<>"']/g,v=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[v]));
const norm=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const titlecase=x=>String(x||'').toLocaleLowerCase('pt-BR').replace(/(^|\s|[-])([a-zà-ú])/g,(w,p,l)=>p+l.toLocaleUpperCase('pt-BR'));
const abbrev=x=>String(x||'?').trim().split(/\s+/).slice(0,2).map(y=>y[0]).join('').toUpperCase();
const fmtDate=x=>{if(!x)return'—';try{if(/^\d{4}-\d\d-\d\d/.test(x))return new Date(x.slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR');return x}catch{return x}};
const queryString=(o)=>Object.entries(o).filter(([k,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>encodeURIComponent(k)+'='+encodeURIComponent(v)).join('&');
const newId=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random().toString(36).slice(2);
let db=null;let people=[...SEED.senators,...SEED.historical];let deputies=[];let senatorLive=[];let syncedAt=null;let catalog=[];let records=[];let lastError='';let legislation=[];let votes=[];
const state={route:'inicio',id:'',tab:'resumo',q:'',party:'',uf:'',kind:'',page:1,partyQ:'',legalQ:'',legalType:'',legalYear:'',legalStatus:'',voteQ:'',compare:['','',''],detected:'',limit:30,year:'2025',recordFilter:'',legalBusy:false,votesBusy:false,detail:null};
const STORE='arquivo-civico-ui-v1';
try{const s=JSON.parse(localStorage.getItem(STORE)||'{}');if(s.theme)document.body.classList.toggle('light',s.theme==='light')}catch{}
function toast(msg){const t=document.createElement('div');t.className='toast';t.textContent=msg;$('#toasts').appendChild(t);setTimeout(()=>t.remove(),3400)}
function saveTheme(){try{localStorage.setItem(STORE,JSON.stringify({theme:document.body.classList.contains('light')?'light':'dark'}))}catch{}}
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB'in window)){resolve(null);return}const req=indexedDB.open('arquivo-civico-official-v1',1);req.onupgradeneeded=()=>{const d=req.result;for(const n of ['datasets','research'])if(!d.objectStoreNames.contains(n))d.createObjectStore(n,{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbPut(table,key,value){if(!db)return Promise.resolve();return new Promise((resolve,reject)=>{const tx=db.transaction(table,'readwrite');tx.objectStore(table).put({key,value});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function dbGet(table,key){if(!db)return Promise.resolve(null);return new Promise(resolve=>{const tx=db.transaction(table,'readonly');const r=tx.objectStore(table).get(key);r.onsuccess=()=>resolve(r.result?.value||null);r.onerror=()=>resolve(null)})}
function dbAll(table){if(!db)return Promise.resolve([]);return new Promise(resolve=>{const r=db.transaction(table,'readonly').objectStore(table).getAll();r.onsuccess=()=>resolve((r.result||[]).map(x=>x.value));r.onerror=()=>resolve([])})}
function listUnique(items){const m=new Map();for(const x of items){const key=x.camara==='Câmara'?`d-${x.id}`:x.camara==='Senado'?`s-${norm(x.nome)}`:x.id;m.set(key,x)}return[...m.values()]}
function regroup(){people=listUnique([...SEED.senators,...senatorLive,...SEED.historical,...deputies]);$('#rail-sync-state').textContent=syncedAt?`Última carga da Câmara: ${fmtDate(syncedAt)}. Senado/TSE: consulte a data em cada ficha.`:'Acervo oficial de referência: 26/10/2026. Carregamento da Câmara sob demanda.'}
function routeTo(path){location.hash='#/'+path}
function readRoute(){const seg=decodeURIComponent((location.hash||'#/inicio').replace(/^#\/?/,'')).split('/').filter(Boolean);state.route=seg[0]||'inicio';state.id=seg.slice(1).join('/');state.tab='resumo';state.page=1;render();window.scrollTo({top:0,behavior:'instant'});$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('open')}
function navActivate(){const parent=['politico','pessoa'].includes(state.route)?'politicos':state.route==='partido'?'partidos':state.route==='proposicao'?'legislacao':state.route==='votacao'?'votacoes':state.route;$$('#sidebar nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===parent))}
const link=(url,label='Ver documento')=>url&&/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const badge=(s,cls='')=>`<span class="pill ${cls}">${esc(s)}</span>`;
const header=(k,title,sub,action='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(k)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action?`<div class="page-actions">${action}</div>`:''}</div>`;
const sourceCard=(title,desc,url,provider='FONTE INSTITUCIONAL')=>`<div class="source-card"><div class="eyebrow">${esc(provider)}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${link(url,'Abrir registro oficial')}</div>`;
const sourceRow=(name,desc,url)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><span class="source-initial">▣</span><span><strong>${esc(name)}</strong><small>${esc(desc)}</small></span><span>↗</span></a>`;
const personCard=(x)=>`<a href="#/politico/${encodeURIComponent(x.id)}" class="entity-card card-link"><div class="entity-card-head"><div class="avatar">${x.foto?`<img loading="lazy" src="${esc(x.foto)}" alt="Foto institucional de ${esc(x.nome)}" onerror="this.remove()">`:esc(abbrev(x.nome))}</div><div style="min-width:0"><h3>${esc(x.nome)}</h3><p>${esc(x.camara||'Histórico')} · ${esc(x.uf||'Brasil')}</p></div></div><div class="entity-card-foot">${badge(x.partido||'Filiação não catalogada','grey')}<span>Abrir ficha →</span></div></a>`;
const partyCard=(p)=>`<a class="entity-card card-link" href="#/partido/${encodeURIComponent(p.sigla)}"><div class="entity-card-head"><div class="party-square">${esc(p.sigla.length>7?p.sigla.slice(0,6):p.sigla)}</div><div style="min-width:0"><h3>${esc(p.sigla)}</h3><p style="white-space:normal">${esc(p.nome)}</p></div></div><div class="entity-card-foot"><small>Nº ${p.numero} · registro ${p.deferimento.slice(-4)}</small><span>Ver partido →</span></div></a>`;
const politicianSources=x=>`${sourceRow(x.camara==='Câmara'?'Câmara dos Deputados':x.camara==='Senado'?'Senado Federal':'Presidência / Planalto','Registro institucional, sujeito a alterações',x.source||URLS.CAM)}${x.camara==='Câmara'&&x.id?sourceRow('Perfil parlamentar oficial','Detalhes e dados cadastrais',`https://www.camara.leg.br/deputados/${x.apiId||x.id}`):''}${sourceRow('TSE — registros eleitorais','Bens declarados, candidatura e contas quando disponíveis',URLS.TSE_DATA)}`;
function renderHome(){const countC=deputies.length,sen=SEED.senators.length,pt=SEED.parties.length;const snapshot=!!countC;return `<section class="hero"><div class="hero-content"><div class="eyebrow">ENCICLOPÉDIA DOCUMENTAL · BRASIL</div><h1>O poder público,<br><em>com fontes à vista.</em></h1><p>Conheça políticos, partidos, proposições, votações e processos a partir de registros oficiais. Sem notas políticas, acusações sem prova ou números inventados.</p><div class="hero-controls"><button class="btn btn-primary" data-action="view" data-to="politicos">Explorar políticos <span>↗</span></button><button class="btn btn-outline" data-action="view" data-to="partidos">Partidos e história</button></div></div><div class="hero-art"><div class="ring"></div><div class="tower a"></div><div class="tower b"></div><div class="dome"></div></div></section>
<div class="stat-grid"><div class="stat-card"><span class="kicker">CÂMARA DOS DEPUTADOS</span><b>${snapshot?countC:'—'}</b><small>${snapshot?'Registros carregados da API oficial':'Clique em “Atualizar da Câmara” para carregar'}</small></div><div class="stat-card"><span class="kicker">SENADO FEDERAL</span><b>${sen}</b><small>Registros na lista oficial de 25/10/2026</small></div><div class="stat-card"><span class="kicker">PARTIDOS NO TSE</span><b>${pt}</b><small>Registro consultado em 26/10/2026</small></div><div class="stat-card"><span class="kicker">FEDERAÇÕES</span><b>${SEED.federations.length}</b><small>Federações registradas segundo o TSE</small></div></div>
<div class="section-head"><div><h2>Explore o acervo</h2><p>Investigue temas e documentos por instituição, partido ou parlamentar.</p></div></div><div class="feature-grid"><a href="#/politicos" class="feature-card"><div class="feature-icon">♙</div><h3>Atlas de políticos</h3><p>Fichas de parlamentares, identificação partidária, mandatos e documentos.</p><div class="more">Abrir catálogo →</div></a><a href="#/partidos" class="feature-card"><div class="feature-icon">◈</div><h3>Partidos e federações</h3><p>Registro no TSE, dirigentes, histórico de fusões e vínculos parlamentares.</p><div class="more">Explorar partidos →</div></a><a href="#/legislacao" class="feature-card"><div class="feature-icon">▤</div><h3>Projetos e leis</h3><p>Proposições e PECs com ementa, trâmite e acesso ao texto oficial.</p><div class="more">Abrir proposições →</div></a><a href="#/votacoes" class="feature-card"><div class="feature-icon">≡</div><h3>Votações nominais</h3><p>Votos publicados pela Câmara com data, identificação e registro.</p><div class="more">Consultar votações →</div></a><a href="#/comparar" class="feature-card"><div class="feature-icon">⇄</div><h3>Comparador factual</h3><p>Observe lado a lado dados registrados, sem estabelecer vencedores ou notas.</p><div class="more">Comparar →</div></a><a href="#/investigacoes" class="feature-card"><div class="feature-icon">◇</div><h3>Arquivo de processos</h3><p>Pesquisa e registro documental com distinção entre alegação e decisão.</p><div class="more">Abrir acervo →</div></a></div>
<div class="section-head"><div><h2>Pessoas no acervo</h2><p>Seleção alfabética de nomes; não constitui recomendação política.</p></div><a href="#/politicos">Ver lista completa →</a></div><div class="grid-people">${[...people].sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR')).slice(0,6).map(personCard).join('')}</div>
<div class="section-head"><div><h2>Retrato partidário do Senado</h2><p>Quantidade de nomes na lista oficial de 25/10/2026; não é projeção eleitoral nem uma avaliação política.</p></div><a href="${URLS.SEN}" target="_blank" rel="noopener">Fonte Senado ↗</a></div><div class="panel"><div class="two-cols"><div><h3 class="panel-title">Registros por sigla partidária</h3>${Object.entries(SEED.senators.reduce((a,p)=>(a[p.partido]=(a[p.partido]||0)+1,a),{})).sort(([a],[b])=>a.localeCompare(b)).map(([party,count])=>`<div class="scale-row"><span>${esc(party)}</span><div class="progress"><i style="width:${Math.max(3,100*count/SEED.senators.length)}%"></i></div><strong>${count}</strong></div>`).join('')}</div><div><h3 class="panel-title">Como interpretar</h3><p class="small muted" style="line-height:1.9">Este gráfico mostra quantos nomes de cada sigla aparecem no conjunto de 81 registros publicados pelo Senado em 25 de outubro de 2026. Ele não distingue todos os efeitos de suplência, licença, afastamento ou mudanças posteriores.</p><div class="gov-portal"><strong>Não é um painel de força política</strong><p class="microcopy">Os valores são contagens de registros, não notas de desempenho, chances eleitorais ou apoio popular.</p></div><p class="microcopy">${link(URLS.SEN,'Conferir composição no Senado')}</p></div></div></div><div class="section-head"><div><h2>Instituições e fontes</h2><p>Consulte documentos nas páginas oficiais antes de tirar conclusões.</p></div></div><div class="two-cols"><div class="panel"><div class="panel-header"><h3>O que está dentro da base?</h3>${badge('Acervo inicial','blue')}</div><div class="detail-row"><span>Senadores</span><strong>${sen} entradas datadas</strong></div><div class="detail-row"><span>Partidos</span><strong>${pt} registros TSE</strong></div><div class="detail-row"><span>Parlamentares da Câmara</span><strong>${countC?countC+' registros carregados':'carregamento disponível'}</strong></div><div class="detail-row"><span>Processos judiciais validados</span><strong>sem dossiês individuais pré-preenchidos</strong></div><p class="microcopy">O recorte não permite inferir ausência de investigações; significa apenas que nenhum vínculo judicial foi lançado sem verificação específica.</p></div><div class="panel"><div class="panel-header"><h3>Atualização e rastreabilidade</h3><span class="dot-online"></span></div><p class="small muted" style="line-height:1.8">Câmara e Senado oferecem bases que podem mudar diariamente. A versão inicial funciona offline com registros do Senado e TSE, e permite buscar dados adicionais onde houver acesso à API.</p><button class="btn btn-primary" data-action="sync" style="width:100%;margin-top:12px">↻ Atualizar base da Câmara</button><p class="microcopy">O acesso à API pode depender das permissões de rede e de CORS do navegador.</p></div></div>`}
function renderPeople(){const q=norm(state.q),u=state.uf,p=state.party,k=state.kind;let list=people.filter(x=>(!q||norm(x.nome+' '+(x.partido||'')+' '+(x.uf||'')).includes(q))&&(!u||x.uf===u)&&(!p||x.partido===p)&&(!k||x.camara===k)).sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR'));
const partyNames=[...new Set(people.map(x=>x.partido).filter(Boolean))].sort();const ufs=[...new Set(people.map(x=>x.uf).filter(Boolean))].sort();const limit=state.page*24;return header('ACERVO DE PESSOAS','Políticos brasileiros','Busque por nome, esfera e filiação registrada em fonte oficial.',`<button class="btn btn-outline" data-action="sync">↻ Atualizar da Câmara</button>`)+`<div class="filters"><input class="filter-input" id="people-search" placeholder="Nome, partido ou estado" value="${esc(state.q)}" aria-label="Buscar políticos"><select class="filter-select" id="people-type"><option value="">Todas as esferas</option>${['Câmara','Senado','Executivo / histórico'].map(x=>`<option ${x===k?'selected':''}>${esc(x)}</option>`).join('')}</select><select class="filter-select" id="people-party"><option value="">Todos os partidos</option>${partyNames.map(x=>`<option ${x===p?'selected':''}>${esc(x)}</option>`).join('')}</select><select class="filter-select" id="people-uf"><option value="">Todos os estados</option>${ufs.map(x=>`<option ${x===u?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="result-count">${list.length} pessoas encontradas · Dados do Senado de 25/10/2026; dados da Câmara carregados da API quando disponíveis.</div>${list.length?`<div class="grid-people">${list.slice(0,limit).map(personCard).join('')}</div>${list.length>limit?`<div class="pager"><button class="btn btn-outline" data-action="more">Carregar mais pessoas ↓</button></div>`:''}`:'<div class="empty"><strong>Nenhum nome encontrado</strong>Limpe os filtros ou carregue a base de deputados da Câmara.</div>'}`}
function renderParties(){const list=SEED.parties.filter(p=>norm(p.sigla+' '+p.nome).includes(norm(state.partyQ))).sort((a,b)=>a.sigla.localeCompare(b.sigla));return header('PARTIDOS POLÍTICOS','Registro, identidade e trajetória','Relação de agremiações com registro no TSE. A data exibida é a de deferimento do registro — não necessariamente a fundação histórica.',`<a class="btn btn-outline" target="_blank" rel="noopener" href="${URLS.TSE}">Conferir TSE ↗</a>`)+`<div class="filters"><input id="party-search" class="filter-input" placeholder="Buscar por nome ou sigla" value="${esc(state.partyQ)}"></div><div class="result-count">${list.length} partidos oficiais no recorte de 26/10/2026</div><div class="grid-parties">${list.map(partyCard).join('')}</div><div class="note-box"><strong>Sobre escândalos e investigações:</strong> não existe um indicador oficial único e homogêneo que autorize resumir a situação de um partido como se todos os filiados fossem responsáveis pelos mesmos fatos. O catálogo de processos exige autoria, número, órgão, fase, data e fonte documental individualizados.</div>`}
function renderParty(){const p=SEED.parties.find(x=>x.sigla===state.id);if(!p)return `<div class="empty">Partido não encontrado. <a href="#/partidos">Voltar ao índice</a></div>`;const members=people.filter(x=>x.partido===p.sigla);const federal=SEED.federations.filter(x=>x.siglas.includes(p.sigla));const changes=SEED.changes.filter(x=>x.siglas.includes(p.sigla));const tab=state.tab;return `<div class="eyebrow" style="margin-bottom:14px"><a href="#/partidos" class="muted">PARTIDOS</a> / ${esc(p.sigla)}</div><div class="entity-banner"><div class="banner-main"><div class="party-square" style="width:90px;height:90px;font-size:19px">${esc(p.sigla)}</div><div><div class="eyebrow">REGISTRO ELEITORAL · TSE</div><h1>${esc(p.nome)}</h1><div class="banner-meta">${badge(p.sigla)}${badge('Número '+p.numero,'blue')}${badge('Deferimento '+p.deferimento,'grey')}</div></div></div></div><div class="tabstrip">${[['resumo','Visão geral'],['historico','História e fundação'],['membros','Parlamentares'],['federacao','Federações'],['processos','Processos e contas'],['fontes','Fontes oficiais']].map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div><div id="tab-content">${tab==='resumo'?`<div class="two-cols"><div class="panel"><h3 class="panel-title">Dados cadastrais do TSE</h3>${row('Sigla',p.sigla)}${row('Nome registrado',p.nome)}${row('Número eleitoral',String(p.numero))}${row('Deferimento do registro',p.deferimento)}${row('Dirigente nacional listado pelo TSE',p.dirigente)}<p class="microcopy">Diretoria e situação do registro podem mudar; verifique a fonte antes de republicar.</p></div><div class="panel"><h3 class="panel-title">Representação no acervo</h3><div class="fact-grid"><div class="fact"><label>Registros vinculados</label><strong>${members.length}</strong></div><div class="fact"><label>Federações</label><strong>${federal.length}</strong></div></div><div class="note-box">A contagem inclui apenas políticos com partido catalogado no recorte; não representa o total de filiados ou a composição atual do Congresso.</div></div></div>`:tab==='historico'?`<div class="two-cols"><div class="panel"><h3 class="panel-title">Linha do tempo documentada</h3><div class="timeline"><div class="timeline-item"><small>${p.deferimento}</small><h4>Deferimento de registro no TSE</h4><p>A data de deferimento não substitui uma pesquisa de fundação e criação histórica da organização.</p></div>${changes.map(x=>`<div class="timeline-item"><small>${esc(x.date)}</small><h4>${esc(x.title)}</h4>${link(x.link,'Consultar processo / registro TSE')}</div>`).join('')}</div></div><div class="panel"><h3 class="panel-title">Como aprofundar a trajetória</h3><ul class="plain-list"><li>Consultar estatuto, alterações e eventuais mudanças de nome no TSE.</li><li>Identificar fundadores e diretórios a partir de documentos próprios datados.</li><li>Localizar decisões oficiais de fusão e incorporação.</li><li>Não equiparar data de registro à data de criação social do partido.</li></ul><br>${link(p.source,'Consultar estatuto e histórico no TSE')}</div></div>`:tab==='membros'?`<div class="grid-people">${members.length?members.map(personCard).join(''):'<div class="empty">Nenhum parlamentar desta sigla consta da fotografia carregada. Atualize a Câmara ou consulte o Senado.</div>'}</div><p class="microcopy">Filiações referem-se à data da fonte; mudanças posteriores não são refletidas sem atualização.</p>`:tab==='federacao'?`<div class="panel"><h3 class="panel-title">Federação registrada</h3>${federal.length?federal.map(f=>`<div class="record-card"><strong>${esc(f.nome)}</strong><p>Partidos: ${esc(f.siglas.join(' · '))}</p><div class="meta">Registro: ${esc(f.registro)}</div></div>`).join(''):'<div class="empty">Não há federação para esta sigla na relação oficial consultada.</div>'}${sourceRow('TSE — federações','Registros, estatutos e certidões',URLS.FED)}</div>`:tab==='processos'?`<div class="two-cols"><div class="panel"><h3 class="panel-title">Prestação de contas partidárias</h3><p class="small muted">Para identificar processos de contas, despesas, decisões e responsáveis, consulte o registro oficial do TSE. O site não atribui automaticamente ao partido irregularidades de filiados.</p>${sourceRow('TSE — contas partidárias','Portal oficial de contas e decisões','https://www.tse.jus.br/partidos/contas-partidarias')}${sourceRow('TCU — acórdãos','Controle externo e auditorias',URLS.TCU)}</div><div class="panel"><h3 class="panel-title">Dossiês catalogados e verificados</h3><div class="empty"><strong>Não catalogados nesta versão.</strong>Esta ausência não é uma declaração de inexistência de denúncias ou de processos. Cada caso deve ser associado a número, instância, data, resultado e documentos.</div></div></div>`:sourceRow('Cadastro e histórico — TSE','Número, estatuto, diretório e deferimento',p.source)+sourceRow('Federações — TSE','Relação e situação dos registros',URLS.FED)+sourceRow('Dados eleitorais — TSE','Candidaturas e contas',URLS.TSE_DATA)}</div>`}
const row=(label,val)=>`<div class="detail-row"><span>${esc(label)}</span><strong>${esc(val??'Não informado')}</strong></div>`;
function renderPerson(){const x=people.find(y=>y.id===state.id);if(!x)return `<div class="empty">Pessoa não encontrada. <a href="#/politicos">Abrir catálogo</a></div>`;const isDeputy=x.camara==='Câmara';let tab=state.tab;let linkProf=isDeputy?`https://www.camara.leg.br/deputados/${x.apiId||x.id}`:x.source||URLS.SEN;let body='';if(tab==='resumo')body=`<div class="two-cols"><div class="panel"><h3 class="panel-title">Identificação pública</h3>${row('Nome registrado',x.nome)}${row('Esfera / cargo',x.camara)}${row('Sigla partidária (data da fonte)',x.partido||'Não catalogada')}${row('Unidade da Federação',x.uf||'Não catalogada')}${row('Data da informação',x.sourceDate||'Fonte institucional')}<div class="note-box"><strong>Atenção ao período:</strong> filiações, mandatos e funções mudam. Estes campos representam o registro consultado, não um julgamento ou um histórico completo.</div></div><div class="panel"><h3 class="panel-title">O que pode ser verificado</h3>${politicianSources(x)}</div></div>`;
if(tab==='proposicoes')body=isDeputy?`<div class="panel"><div class="panel-header"><h3>Proposições vinculadas ao parlamentar</h3><button class="btn btn-outline" data-action="person-props" data-id="${esc(x.id)}">↻ Consultar Câmara</button></div><div id="person-results" class="empty">Clique em consultar para buscar autoria de proposições no banco oficial da Câmara. A autoria não significa aprovação.</div></div>`:`<div class="panel"><div class="empty">Integração de autoria não habilitada para este registro. Consulte os dados legislativos do Senado ou a fonte institucional específica.</div>${sourceRow('Senado — autoria e relatoria','Matérias legislativas por parlamentar','https://www12.senado.leg.br/dados-abertos/legislativo/parlamentares')}</div>`;
if(tab==='votacoes')body=`<div class="panel"><h3 class="panel-title">Votações individuais</h3><div class="note-box"><strong>O voto tem que estar documentado.</strong>O site não atribui posicionamentos por partido nem faz estimativas. Para deputados, consulte o painel de votações e abra o registro nominal para identificar cada voto. Para o Senado, use a consulta institucional correspondente.</div><div class="page-actions"><a class="btn btn-outline" href="#/votacoes">Buscar votações da Câmara ↗</a>${link(URLS.SEN,'Dados de votações no Senado')}</div></div>`;
if(tab==='despesas')body=isDeputy?`<div class="panel"><div class="panel-header"><h3>Despesas da atividade parlamentar</h3></div><div class="filters"><select id="expense-year" class="filter-select">${[2026,2025,2024,2023,2022].map(n=>`<option ${state.year==n?'selected':''}>${n}</option>`).join('')}</select><button class="btn btn-outline" data-action="expenses" data-id="${esc(x.id)}">Consultar despesas oficiais</button></div><div id="expense-results" class="empty">Consulta diretamente à Câmara. Valores são apenas dos itens retornados e não constituem totais anuais.</div></div>`:`<div class="panel"><h3>Dados de gastos e despesas</h3><p class="small muted">Os dados de despesas devem ser consultados por modalidade e instituição. Não se deve comparar reembolsos sem distinguir natureza, período e regras.</p>${sourceRow('Portal da Transparência','Despesas e transferências do governo federal',URLS.CGU)}${sourceRow('Senado Federal','Portais de transparência do Senado','https://www12.senado.leg.br/transparencia/')}</div>`;
if(tab==='investigacoes')body=`<div class="two-cols"><div class="panel"><h3 class="panel-title">Processos judiciais e investigações</h3><div class="empty"><strong>Nenhum caso individual validado nesta ficha.</strong>Isso não demonstra inexistência de processos. Antes de relacionar uma pessoa a um caso, é obrigatório confirmar identidade, número do processo, autoridade, fase e última decisão em documento oficial.</div></div><div class="panel"><h3 class="panel-title">Portais para verificação documental</h3>${sourceRow('STF','Jurisprudência e andamento processual',URLS.STF)}${sourceRow('STJ','Processos e decisões',URLS.STJ)}${sourceRow('TCU','Auditorias e acórdãos',URLS.TCU)}${sourceRow('CGU','Transparência e auditorias',URLS.CGU)}</div></div>`;
if(tab==='fontes')body=`<div class="panel"><h3 class="panel-title">Rastreabilidade deste perfil</h3>${politicianSources(x)}<div class="note-box">O perfil é um ponto de partida. Não contém condenações, posições políticas, valor de patrimônio, votos ou estatísticas sem o documento específico correspondente.</div></div>`;
if(tab==='historico')body=`<div class="two-cols"><div class="panel"><h3 class="panel-title">Linha do tempo verificável</h3><div class="timeline"><div class="timeline-item"><small>${esc(x.sourceDate||'Registro sem data consolidada')}</small><h4>Identificação no acervo oficial</h4><p>Parlamentar ou figura histórica identificada por registro institucional.</p></div></div><div class="note-box">Mandatos anteriores, eleições e outras filiações dependem de consulta histórica à instituição; não são inferidos a partir do cargo atual.</div></div><div class="panel"><h3 class="panel-title">Continuar a investigação documental</h3>${politicianSources(x)}</div></div>`;
return `<div class="eyebrow" style="margin-bottom:14px"><a href="#/politicos" class="muted">PESSOAS</a> / ${esc(x.nome)}</div><div class="entity-banner"><div class="banner-main"><div class="avatar large">${x.foto?`<img src="${esc(x.foto)}" alt="Foto institucional" onerror="this.remove()">`:esc(abbrev(x.nome))}</div><div><div class="eyebrow">FICHA DOCUMENTAL · ${esc(x.camara.toUpperCase())}</div><h1>${esc(x.nome)}</h1><div class="banner-meta">${badge(x.partido||'Filiação não catalogada')}${x.uf?badge(x.uf,'blue'):''}${badge('Fonte institucional','grey')}</div><p style="margin-top:11px">${esc(x.descricao||'Identificação do registro público. Dados legislativos e eleitorais exigem consulta específica.')}</p></div></div></div><div class="tabstrip">${[['resumo','Resumo'],['historico','Trajetória'],['proposicoes','Proposições'],['votacoes','Votações'],['despesas','Gastos'],['investigacoes','Processos'],['fontes','Fontes']].map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div>${body}<div class="section-head"><div><h2>Consultar o documento original</h2><p>Verificação primária da identificação e do período do registro.</p></div></div>${sourceRow('Ficha institucional',x.camara==='Senado'?'Relação do Senado consultada em 25/10/2026':x.camara==='Câmara'?'Portal oficial do parlamentar':'Atos da Presidência',linkProf)}`}
function renderFeds(){return header('ORGANIZAÇÃO ELEITORAL','Federações partidárias','Registro e composição informados pelo Tribunal Superior Eleitoral.',`<a href="${URLS.FED}" target="_blank" rel="noopener" class="btn btn-outline">Conferir TSE ↗</a>`)+`<div class="grid-parties">${SEED.federations.map(f=>`<div class="entity-card"><div class="eyebrow">REGISTRO ${esc(f.registro)}</div><h3 style="font-size:17px;white-space:normal;margin:11px 0">${esc(f.nome)}</h3><div class="insight-strip">${f.siglas.map(x=>`<a href="#/partido/${encodeURIComponent(x)}">${badge(x,'blue')}</a>`).join('')}</div><p style="margin-top:15px;line-height:1.7">Os partidos da federação formam uma união partidária regulada pela legislação eleitoral.</p></div>`).join('')}</div>`}
async function safeFetch(url,ms=15000){const ctl=new AbortController();const to=setTimeout(()=>ctl.abort(),ms);try{const r=await fetch(url,{headers:{Accept:'application/json'},signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(to)}}
async function syncCamara(){const btn=$('#rail-sync-btn');if(btn){btn.disabled=true;btn.textContent='Consultando dados...'}toast('Buscando deputados na API oficial da Câmara');try{let out=[],current=1;for(let j=0;j<12;j++){const d=await safeFetch(`${CAM}/deputados?${queryString({itens:100,pagina:current,ordem:'ASC',ordenarPor:'nome'})}`,18000);const x=d.dados||[];out.push(...x);if(x.length<100||!d.links?.some(l=>l.rel==='next'))break;current++}if(!out.length)throw Error('Resposta sem parlamentares');deputies=out.map(x=>({id:'dep'+x.id,apiId:x.id,nome:x.nome,partido:x.siglaPartido,uf:x.siglaUf,camara:'Câmara',foto:x.urlFoto,source:`https://www.camara.leg.br/deputados/${x.apiId||x.id}`,sourceDate:new Date().toISOString().slice(0,10),kind:'api'}));syncedAt=new Date().toISOString();await dbPut('datasets','camara',{items:deputies,syncedAt});regroup();toast(`${deputies.length} registros da Câmara carregados`);render()}catch(e){lastError=e.message;toast('Não foi possível acessar a Câmara: '+lastError);render()}finally{if(btn){btn.disabled=false;btn.textContent='↻ Atualizar da Câmara'}}}
async function syncSenate(){try{const d=await safeFetch(SEN,13000);if(!Array.isArray(d.data))throw Error('Dados não reconhecidos');senatorLive=d.data.map((x,i)=>({id:'sen'+(i+1),nome:titlecase(x.nomeParlamentar),partido:x.partido,uf:x.uf,camara:'Senado',source:'https://adm.senado.gov.br/adm-dadosabertos/api/v1/senadores?formato=html',sourceDate:new Date().toISOString().slice(0,10),kind:'api',mandato:x.mandato}));await dbPut('datasets','senate',{items:senatorLive,syncedAt:new Date().toISOString()});regroup();toast('Senado atualizado com '+senatorLive.length+' registros');render()}catch(e){toast('Senado: não foi possível obter resposta na conexão atual')}}
let pendingLegal=null,pendingVotes=null;
async function fetchLegislation(){state.legalBusy=true;render();try{const params={itens:30,ordem:'DESC',ordenarPor:'id'};if(state.legalType)params.siglaTipo=state.legalType;if(state.legalYear)params.ano=state.legalYear;if(state.legalQ)params.keywords=state.legalQ;const d=await safeFetch(`${CAM}/proposicoes?${queryString(params)}`,18000);legislation=(d.dados||[]).map(x=>({id:x.id,leg:x.siglaTipo+' '+x.numero+'/'+x.ano,title:x.ementa,detail:x.uri,source:`https://www.camara.leg.br/propostas-legislativas/${x.id}`}));if(!legislation.length)toast('A consulta não retornou proposições.');else toast(`${legislation.length} proposições obtidas da Câmara.`)}catch(e){lastError=e.message;legislation=[];toast('Consulta legislativa indisponível: '+e.message)}finally{state.legalBusy=false;render()}}
async function fetchVotes(){state.votesBusy=true;render();try{const d=await safeFetch(`${CAM}/votacoes?${queryString({itens:40,ordem:'DESC',ordenarPor:'dataHoraRegistro'})}`);votes=(d.dados||[]).map(x=>({id:x.id,data:x.data||x.dataHoraRegistro||'',orgao:x.siglaOrgao||'',descricao:x.descricao||'',aprovacao:x.aprovacao||0,source:`https://www.camara.leg.br/` }));toast(`${votes.length} votações oficiais obtidas`)}catch(e){votes=[];lastError=e.message;toast('Votações indisponíveis: '+e.message)}finally{state.votesBusy=false;render()}}
function renderLegislation(){return header('TRAMITAÇÃO LEGISLATIVA','Leis, projetos e PECs','Consulte proposições da Câmara. Proposta apresentada não é lei aprovada.',`<a href="${URLS.CAM}" target="_blank" rel="noopener" class="btn btn-outline">Documentação da API ↗</a>`)+`<div class="filters"><input class="filter-input" id="legal-query" placeholder="Assunto ou palavra-chave" value="${esc(state.legalQ)}"><select class="filter-select" id="legal-type">${[['','Todos os tipos'],['PL','Projeto de Lei'],['PEC','PEC'],['PLP','Lei Complementar'],['MPV','Medida Provisória'],['PDL','Decreto Legislativo'],['REQ','Requerimento']].map(([v,n])=>`<option value="${v}" ${state.legalType===v?'selected':''}>${n}</option>`).join('')}</select><select class="filter-select" id="legal-year"><option value="">Todos os anos</option>${Array.from({length:12},(_,i)=>String(2026-i)).map(y=>`<option ${state.legalYear===y?'selected':''}>${y}</option>`).join('')}</select><button class="btn btn-primary" data-action="query-legal" ${state.legalBusy?'disabled':''}>${state.legalBusy?'Consultando...':'Buscar na Câmara'}</button></div><div class="note-box"><strong>Escopo da consulta:</strong> ementa, identificação e link público da proposição na Câmara. Para saber se virou lei, é preciso conferir o histórico de tramitação e a norma publicada. Não há inferência sobre autoria de parlamentares não confirmada.</div><div>${legislation.length?legislation.map(x=>`<div class="record-card"><div class="record-top">${badge(x.leg,'blue')}<small class="muted">ID ${x.id}</small></div><p>${esc(x.title)}</p>${link(x.source,'Ver texto e tramitação na Câmara')} <button class="btn btn-text" data-action="prop-detail" data-id="${x.id}">Ver histórico →</button></div>`).join(''):`<div class="empty"><strong>Consulta legislativa sob demanda</strong>Defina filtros e clique em buscar. Não apresentamos projetos inventados ou dados de tramitação armazenados sem fonte.<p class="microcopy">Caso o navegador bloqueie a API, use o acesso direto à Câmara.</p>${link(URLS.CAM_PROJ,'Pesquisar na Câmara')}</div>`}</div>`}
function renderVotes(){return header('REGISTROS NOMINAIS','Votações da Câmara','Resultados e votos disponíveis no sistema oficial. É necessário abrir cada votação para conferir o voto de cada deputado.',`<a href="${URLS.CAM}" target="_blank" rel="noopener" class="btn btn-outline">Fonte oficial ↗</a>`)+`<div class="filters"><input id="votes-query" class="filter-input" placeholder="Filtrar as votações exibidas" value="${esc(state.voteQ)}"><button class="btn btn-primary" data-action="query-votes" ${state.votesBusy?'disabled':''}>${state.votesBusy?'Consultando...':'Buscar votações recentes'}</button></div>${votes.length?votes.filter(x=>norm(x.descricao+' '+x.id).includes(norm(state.voteQ))).map(x=>`<div class="record-card"><div class="record-top">${badge(fmtDate(x.data),'blue')}<span class="microcopy">${esc(x.orgao||'Câmara')}</span></div><strong>${esc(x.descricao||'Votação identificada por código '+x.id)}</strong><p>Registro: ${esc(x.id)}. Clique para consultar os votos nominais publicados.</p><button class="btn btn-outline" data-action="vote-detail" data-id="${esc(x.id)}">Abrir votos nominais ↗</button></div>`).join(''):`<div class="empty"><strong>Votações disponíveis por consulta</strong>Use a busca para solicitar os registros mais recentes à API oficial da Câmara. Não mostramos supostas posições partidárias sem votação nominal identificada.</div>`}`}
async function openVoteDetail(id){showModal('Votação nominal '+id,'Consultando registro oficial...');try{const d=await safeFetch(`${CAM}/votacoes/${encodeURIComponent(id)}/votos?itens=100`,20000);const arr=d.dados||[];$('#modal-content').innerHTML=`<p class="microcopy">Votos nominais retornados pela Câmara. Amostra limitada ao número de itens requisitados; não representa necessariamente o total de votantes.</p><div class="record-card">${arr.length?arr.map(x=>`<div class="detail-row"><span>${esc(x.deputado_?.nome||'Nome não informado')}</span><strong>${esc(x.tipoVoto||'Não informado')}</strong></div>`).join(''):'O registro não retornou votos nominais nesta chamada.'}</div>${link(`${CAM}/votacoes/${encodeURIComponent(id)}/votos`,'Abrir dados originais')}`}catch(e){$('#modal-content').textContent='Falha no acesso à API: '+e.message}}
async function fetchPersonProps(id){const x=people.find(p=>p.id===id);const target=$('#person-results');if(!x?.apiId||!target)return;target.textContent='Consultando proposições oficiais...';try{const d=await safeFetch(`${CAM}/proposicoes?${queryString({idDeputadoAutor:x.apiId,itens:35,ordem:'DESC',ordenarPor:'id'})}`,20000);const arr=d.dados||[];target.className='';target.innerHTML=arr.length?arr.map(p=>`<div class="record-card">${badge(p.siglaTipo+' '+p.numero+'/'+p.ano,'blue')}<p>${esc(p.ementa)}</p>${link('https://www.camara.leg.br/propostas-legislativas/'+p.id,'Verificar autoria e tramitação')}</div>`).join(''):'Nenhuma proposição retornada com esse filtro. Verifique a ficha na Câmara.'}catch(e){target.className='empty';target.textContent='Consulta indisponível: '+e.message}}
async function fetchExpenses(id){const x=people.find(p=>p.id===id),target=$('#expense-results');if(!x?.apiId||!target)return;target.textContent='Consultando despesas oficiais...';try{const d=await safeFetch(`${CAM}/deputados/${x.apiId}/despesas?${queryString({ano:state.year,itens:30,ordem:'DESC',ordenarPor:'dataDocumento'})}`);const arr=d.dados||[];target.className='';target.innerHTML=`<p class="microcopy">Mostrando no máximo ${arr.length} itens retornados, sem extrapolar valores para todo o ano. Verifique documentos e notas na Câmara.</p>${arr.map(y=>`<div class="record-card"><strong>${esc(y.tipoDespesa||'Despesa registrada')}</strong><p>${esc(y.nomeFornecedor||'Fornecedor não informado')} · ${esc(fmtDate(y.dataDocumento))}</p><div class="meta">Valor do documento: ${typeof y.valorDocumento==='number'?y.valorDocumento.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'não informado'}</div></div>`).join('')}`||'Nenhum item retornado.'}catch(e){target.className='empty';target.textContent='Consulta indisponível: '+e.message}}
async function detailProposition(id){showModal('Tramitação e histórico','Acessando registro...');try{const [info,steps]=await Promise.all([safeFetch(`${CAM}/proposicoes/${id}`),safeFetch(`${CAM}/proposicoes/${id}/tramitacoes?itens=15&ordem=DESC&ordenarPor=dataHora`)]);const p=info.dados||{};$('#modal-content').innerHTML=`<div class="record-card"><strong>${esc(p.siglaTipo+' '+p.numero+'/'+p.ano)}</strong><p>${esc(p.ementa||'')}</p>${row('Situação',p.statusProposicao?.descricaoSituacao||'Ver tramitação')}${link(`https://www.camara.leg.br/propostas-legislativas/${id}`,'Texto e ficha oficial')}</div><h3>Movimentações retornadas</h3>${(steps.dados||[]).map(y=>`<div class="timeline-item"><small>${esc(fmtDate(y.dataHora))}</small><p>${esc(y.descricaoTramitacao||y.despacho||'Registro de tramitação')}</p></div>`).join('')}`}catch(e){$('#modal-content').textContent='Falha ao obter detalhes: '+e.message}}
function renderCompare(){const options=`<option value="">Selecione uma pessoa</option>${[...people].sort((a,b)=>a.nome.localeCompare(b.nome,'pt-BR')).map(x=>`<option value="${esc(x.id)}">${esc(x.nome)} (${esc(x.camara)})</option>`).join('')}`;const selected=state.compare.map(k=>people.find(x=>x.id===k));const names=selected.map(x=>x?.nome||'—');const rows=[['Nome',...names],['Esfera',...selected.map(x=>x?.camara||'—')],['Partido no recorte da fonte',...selected.map(x=>x?.partido||'—')],['UF',...selected.map(x=>x?.uf||'—')],['Origem do registro',...selected.map(x=>x?.fonte||x?.camara||'—')],['Data do registro',...selected.map(x=>x?.sourceDate||'—')],['Dados de votação individual',...selected.map(x=>x?'Requer consulta nominal oficial':'—')],['Situação judicial',...selected.map(x=>x?'Nenhum dossiê judicial validado nesta versão':'—')]];return header('COMPARAÇÃO DESCRITIVA','Comparar informações','Compare registros verificáveis lado a lado, sem julgamento, pontuação ou classificação.',`<button class="btn btn-outline" data-action="export-compare">Exportar JSON</button>`)+`<div class="panel"><h3 class="panel-title">Selecione até três pessoas</h3><div class="compare-controls">${state.compare.map((v,i)=>`<select class="filter-select compare-select" data-index="${i}">${options.replace(`value="${esc(v)}"`,`value="${esc(v)}" selected`)}</select>`).join('')}</div><p class="microcopy">Comparação limitada aos mesmos campos de dados. Não indica desempenho, caráter, probidade ou qual opção seria melhor.</p><div class="table-wrap"><table class="compare-table"><thead><tr><th>Dado</th>${names.map(n=>`<th>${esc(n)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function renderInvestigations(){const filtered=records.filter(x=>!state.recordFilter||norm(x.titulo+' '+x.orgao).includes(norm(state.recordFilter)));return header('DOCUMENTOS E PROCESSOS','Investigações e controle público','Alegação, investigação, denúncia, ação e condenação são etapas diferentes — não se confundem.',`<button class="btn btn-outline" data-action="new-note">+ Registro de pesquisa local</button>`)+`<div class="note-box"><strong>Proteção contra desinformação:</strong> este acervo não publica acusações sem documento primário verificável nem associa casos automaticamente a um partido. O registro de pesquisa é privado neste navegador e não é validação judicial ou editorial.</div><div class="two-cols"><div class="panel"><h3 class="panel-title">Entenda a situação processual</h3>${[['Notícia ou alegação','Declaração ou relato; não implica investigação formal.'],['Inquérito / investigação','Apuração conduzida por autoridade competente; não significa culpa.'],['Denúncia','Acusação formal apresentada ao órgão judicial competente; é diferente de condenação.'],['Processo e decisão','A decisão precisa ter data, órgão, instância e status de recurso.'],['Trânsito em julgado','Decisão definitiva, quando não couberem mais recursos.']].map(([a,b])=>`<div class="detail-row" style="display:block"><strong style="text-align:left">${esc(a)}</strong><p class="microcopy">${esc(b)}</p></div>`).join('')}</div><div class="panel"><h3 class="panel-title">Fontes primárias para pesquisar</h3>${sourceRow('STF — processos e decisões','Andamento e jurisprudência',URLS.STF)}${sourceRow('STJ — processos','Decisões judiciais',URLS.STJ)}${sourceRow('TCU — acórdãos','Controle externo, contas e auditorias',URLS.TCU)}${sourceRow('CGU — transparência e auditoria','Dados governamentais',URLS.CGU)}${sourceRow('TSE — prestações de contas','Partidos e candidaturas',URLS.TSE_DATA)}</div></div><div class="section-head"><div><h2>Caderno de pesquisa local</h2><p>Informações privadas adicionadas por você; nunca apresentadas como confirmação oficial.</p></div></div><div class="filters"><input class="filter-input" id="record-search" value="${esc(state.recordFilter)}" placeholder="Filtrar minhas anotações"><button class="btn btn-outline" data-action="export-notes">Exportar notas JSON</button></div>${filtered.length?filtered.map(x=>`<div class="record-card"><div class="record-top"><strong>${esc(x.titulo)}</strong>${badge('NÃO VALIDADO','warn')}</div><p>${esc(x.resumo)}</p><div class="meta">Órgão informado: ${esc(x.orgao||'não informado')} · Registrado: ${esc(fmtDate(x.criado))}</div>${link(x.url,'Conferir documento informado')}</div>`).join(''):'<div class="empty"><strong>Nenhuma anotação local cadastrada</strong>Pesquise fontes primárias e registre sua própria investigação documental. Registros locais não se tornam automaticamente fatos publicados.</div>'}`}
function renderSources(){return header('TRANSPARÊNCIA E RASTREABILIDADE','Fontes institucionais','Acesso à origem da informação. Registros podem ser alterados pelas instituições após a data da consulta.')+`<div class="source-list">${[
['Câmara dos Deputados','Deputados, proposições, autores, tramitações, votações nominais e despesas.',URLS.CAM,'API / LEGISLATIVO'],['Senado Federal','Senadores, mandatos, matérias, discursos e votações; dados abertos.',URLS.SEN,'API / LEGISLATIVO'],['Tribunal Superior Eleitoral','Registros de partidos, estatutos, números e deferimentos.',URLS.TSE,'PARTIDOS'],['TSE — Federações','Composição, datas de registro e estatutos das federações.',URLS.FED,'PARTIDOS'],['Dados Abertos do TSE','Candidaturas, bens declarados, receitas e despesas eleitorais.',URLS.TSE_DATA,'ELEIÇÕES'],['Tribunal de Contas da União','Acórdãos, auditorias e processos de controle externo.',URLS.TCU,'CONTROLE'],['Controladoria-Geral da União','Portal da Transparência, auditorias e despesas federais.',URLS.CGU,'CONTROLE'],['Supremo Tribunal Federal','Consulta de processos, decisões e jurisprudência.',URLS.STF,'JUSTIÇA'],['Superior Tribunal de Justiça','Jurisprudência e processos judiciais federais.',URLS.STJ,'JUSTIÇA'],['Planalto — Legislação','Textos normativos publicados e consolidados.',URLS.PLANALTO,'LEGISLAÇÃO']].map(z=>sourceCard(...z)).join('')}</div>`}
function renderMethod(){return header('PROTOCOLO DE PUBLICAÇÃO','Método e critérios de evidência','O objetivo não é opinar sobre candidatos, mas permitir que o leitor localize e confira fatos.')+`<div class="two-cols"><div class="panel"><h3 class="panel-title">Protocolo de integridade</h3>${[['1. Identificar a fonte','Exigir órgão emissor, URL oficial, data do documento e número de referência quando aplicável.'],['2. Separar autoria de aprovação','Ter apresentado um PL não significa ter feito aprovar uma lei.'],['3. Verificar o voto nominal','Somente atribuir voto quando constar da lista nominal da sessão pertinente.'],['4. Distinguir situações judiciais','Investigado, denunciado, réu, condenado e absolvido não são sinônimos.'],['5. Tratar o tempo','Partido, cargo e situação processual são sempre dados de um período específico.'],['6. Evitar culpa por associação','Processos individuais não podem ser generalizados automaticamente para todo um partido.'],['7. Não inventar ausências','Registro não encontrado não significa inexistência do fato ou inocência comprovada.'],['8. Informar cobertura','A base é crescente e não representa a totalidade da vida política brasileira.']].map(([a,b])=>`<div class="detail-row" style="display:block"><strong style="text-align:left">${esc(a)}</strong><p class="microcopy">${esc(b)}</p></div>`).join('')}</div><div class="panel"><h3 class="panel-title">Arquitetura de dados</h3>${row('Frontend','HTML, CSS e JavaScript sem framework')}${row('Base inicial','JSON versionado com fontes oficiais')}${row('Dados oficiais dinâmicos','API aberta da Câmara; Senado quando acessível')}${row('Persistência local','IndexedDB (se disponível)')}${row('Dados judiciais','Não catalogados sem validação específica')}${row('Revisão automatizada por IA','Não utilizada')}${row('Dados de exemplo inventados','Não incluídos')}<div class="note-box"><strong>Uso responsável:</strong> imagens de interfaces e material promocional são ilustrativos, mas os cadastros e os números desta aplicação seguem apenas o que foi conferido.</div><button class="btn btn-outline" data-action="export-all" style="width:100%">↓ Exportar banco local JSON</button><br><br><a href="data/seed.json" target="_blank" rel="noopener" class="btn btn-subtle" style="width:100%">Ver base inicial JSON ↗</a></div></div>`}
function showModal(title,html){const old=$('#archive-modal');if(old)old.remove();const wrap=document.createElement('div');wrap.className='floating-modal';wrap.id='archive-modal';wrap.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Fechar">×</button></div><hr><div id="modal-content">${html}</div></div>`;wrap.addEventListener('click',e=>{if(e.target===wrap)wrap.remove()});document.body.appendChild(wrap)}
function newNote(){showModal('Nota documental (privada)',`<div class="note-box"><strong>Não é um registro oficial validado.</strong> Este campo guarda anotações de pesquisa apenas no navegador atual.</div><form id="note-form"><label>Título da anotação<input name="titulo" required maxlength="130" placeholder="Ex.: Processo Nº ..."></label><label>Instituição/órgão<input name="orgao" maxlength="100" placeholder="Ex.: tribunal ou órgão emissor"></label><label>URL do documento oficial<input name="url" type="url" placeholder="https://..."></label><label>Resumo do que a fonte efetivamente demonstra<textarea name="resumo" required rows="4" maxlength="1500" placeholder="Evite conclusões não demonstradas..."></textarea></label><div class="button-row"><button type="button" class="btn btn-outline" data-action="close-modal">Cancelar</button><button class="btn btn-primary">Salvar nota local</button></div></form>`);$('#note-form').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),o={id:newId(),titulo:String(d.get('titulo')),orgao:String(d.get('orgao')),url:String(d.get('url')),resumo:String(d.get('resumo')),criado:new Date().toISOString(),verified:false};records.push(o);await dbPut('research',o.id,o);$('#archive-modal').remove();toast('Nota privada salva');render()}}
function exportData(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function render(){navActivate();let html='';switch(state.route){case'inicio':html=renderHome();break;case'politicos':html=renderPeople();break;case'politico':html=renderPerson();break;case'partidos':html=renderParties();break;case'partido':html=renderParty();break;case'federacoes':html=renderFeds();break;case'legislacao':html=renderLegislation();break;case'votacoes':html=renderVotes();break;case'comparar':html=renderCompare();break;case'investigacoes':html=renderInvestigations();break;case'fontes':html=renderSources();break;case'metodologia':html=renderMethod();break;default:html=renderHome()};$('#main').innerHTML=html}
const handleAction=async(el)=>{const a=el.dataset.action,id=el.dataset.id;if(a==='view')routeTo(el.dataset.to);if(a==='sync')await syncCamara();if(a==='more'){state.page++;render()}if(a==='query-legal')await fetchLegislation();if(a==='query-votes')await fetchVotes();if(a==='vote-detail')await openVoteDetail(id);if(a==='person-props')await fetchPersonProps(id);if(a==='expenses')await fetchExpenses(id);if(a==='prop-detail')await detailProposition(id);if(a==='new-note')newNote();if(a==='close-modal')$('#archive-modal')?.remove();if(a==='export-notes')exportData(records,'arquivo-civico-notas-privadas.json');if(a==='export-all')exportData({seed:SEED,importedDeputies:deputies,importedSenators:senatorLive,privateResearch:records,exportedAt:new Date().toISOString()},'arquivo-civico-base-local.json');if(a==='export-compare')exportData(state.compare.map(id=>people.find(p=>p.id===id)).filter(Boolean),'arquivo-civico-comparativo.json')};
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();handleAction(a)}const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render()}});
document.addEventListener('input',e=>{const id=e.target.id,v=e.target.value;if(id==='people-search'){state.q=v;state.page=1;render();$('#people-search')?.focus();$('#people-search')?.setSelectionRange(v.length,v.length)}if(id==='party-search'){state.partyQ=v;render();$('#party-search')?.focus();$('#party-search')?.setSelectionRange(v.length,v.length)}if(id==='record-search'){state.recordFilter=v;render();$('#record-search')?.focus();$('#record-search')?.setSelectionRange(v.length,v.length)}if(id==='votes-query'){state.voteQ=v;render();$('#votes-query')?.focus();$('#votes-query')?.setSelectionRange(v.length,v.length)}if(id==='legal-query')state.legalQ=v});
document.addEventListener('change',e=>{const el=e.target,id=el.id,v=el.value;if(id==='people-type'){state.kind=v;state.page=1;render()}if(id==='people-party'){state.party=v;state.page=1;render()}if(id==='people-uf'){state.uf=v;state.page=1;render()}if(id==='legal-type')state.legalType=v;if(id==='legal-year')state.legalYear=v;if(id==='expense-year')state.year=v;if(el.classList.contains('compare-select')){state.compare[Number(el.dataset.index)]=v;render()}});
$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){state.q=e.target.value.trim();if(location.hash==='#/politicos')render();else routeTo('politicos')}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement?.tagName)){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape'){$('#archive-modal')?.remove();$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('open')}});
$('#menu-toggle').onclick=()=>{$('#sidebar').classList.toggle('open');$('#mobile-scrim').classList.toggle('open')};$('#mobile-scrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('open')};$('#theme-button').onclick=()=>{document.body.classList.toggle('light');saveTheme()};$('#rail-sync-btn').onclick=syncCamara;
window.addEventListener('hashchange',readRoute);
async function init(){try{db=await openDB();const c=await dbGet('datasets','camara'),s=await dbGet('datasets','senate');if(c?.items){deputies=c.items;syncedAt=c.syncedAt}if(s?.items)senatorLive=s.items;records=await dbAll('research')}catch(e){console.warn('IndexedDB unavailable',e)}try{if(!deputies.length&&location.protocol!=='file:'){const r=await fetch('./data/deputados.json',{cache:'no-cache'});if(r.ok){const payload=await r.json();if(payload.items?.length>400){deputies=payload.items;syncedAt=payload.capturedAt;await dbPut('datasets','camara',{items:deputies,syncedAt})}}}}catch(e){console.warn('Optional snapshot not available',e)}regroup();readRoute()}
init();
})();